internal sealed class DashboardHelp:DashboardDialog {
    internal sealed class Topic {public string Title{get;private set;} internal string Body;internal Topic(string title,string body){Title=title;Body=body;}public override string ToString(){return Title;}}
    internal static readonly Topic[] Topics={
        new Topic("Getting started","Open a sidebar section to find your folders, documents and websites. Tasks shows Task list 1 and Checklists by default. Choose files for Task list 2 or Task list 3 in Settings > Tasks to show those tabs. Rename any list there. Select a list or Checklists in the Tasks sidebar. The main pane shows that list's heading and Search. In Compact view, list buttons stay above the items.\n\nChoose Edit beneath the lists to add, change or remove tasks and checklist items. In Checklists, check off items directly.\n\nTask lists start without selected files. In Settings > Tasks, choose or create a TXT or Markdown file for each list you want to use. Locally synced folders and network shares work with your Windows permissions. Checklists starts ready to use and saves to its own file. Newly selected files load after Save. Opening a task view reads its latest contents. Use Refresh beside Search to reread it manually.\n\nSettings is available in the bottom-left sidebar and File menu. Compact view shrinks the window; Expand returns to the full window and those Settings controls. Dashboard and Compact view remember separate positions and sizes. Settings > Window > Reset window sizes restores their defaults when you choose Save; Cancel keeps the current placement. Other dialogs reopen at their standard sizes. On top keeps it above other windows. Help > Run setup again revisits the optional guide. Use Help > Check for updates to look for the latest stable release."),
        new Topic("Projects, folders and websites","A fresh installation starts with Projects, Documents, Websites and All links. Projects contains Sample project folder, Documents contains Sample project brief, and Websites contains Sample website. All links shows those same three entries together. The example folder and document ship with the app; the example website is example.com. No personal folders or task lists are included.\n\nUse Edit below the sidebar to replace the example name and destination with your own folder, document or website. Folder opens a folder in Explorer. Open opens a document in its Windows app. Website uses Firefox if installed, otherwise your default browser. Changing a destination does not move or copy your files.\n\nExisting profiles retain their saved catalog, categories and labels. An existing category may have its own Open folder action. New profiles do not assume a workspace location. Unavailable destinations are disabled until their saved location is corrected."),
        new Topic("Reorder categories and links","Open Edit below the sidebar. Drag a category by its handle on the left, or drag a link in the selected category on the right. You can also focus a handle and press Ctrl+Up or Ctrl+Down. Save applies the new order. Cancel discards the draft.\r\n\r\nUse Edit to select a dashboard entry and change its display name, destination, or icon. Save applies the changes together. Cancel leaves the catalog as it was. Display names are independent of folder names. If the saved catalog changes while you edit, cancel and reopen Edit before saving again."),
        new Topic("Managing your dashboard","Use Edit below the sidebar to open Edit Dashboard. Add or rename a category, choose an icon, or edit its links in the same window. Remove a category with links by choosing another category for them. All links is the combined view. Show or hide it in Settings > Appearance. Save applies the draft together and Cancel discards it. Choose a category, then Add link. Enter its name, choose Folder, Document or Website under Opens, and enter an address or browse to the location. When you save a website link without a custom icon, Dashboard tries the site and may send its domain to a public icon index if needed. Choose Change link icon to set your own. For a link with several destinations, select a website destination before choosing Use website icon. Save keeps your choice. Dashboard looks for missing automatic website icons when you open a category or refresh the directory. The picker has Common and All icons. Search covers the full collection. Choose Browse local image to use your own image, or Use default icon to reset. Save applies all changes; Cancel discards the draft. Remove link only removes the dashboard entry, never its linked file or folder. A display name does not rename a file or folder.\n\nLinks are saved in catalog.json beside the app. The editor manages entries without manual JSON editing. All links is a browsing view. Open Edit and select a category before editing its links. For a link with several destinations, select the one you want to edit or remove. To remove its last destination, remove the link. Back up configuration before major changes.\n\nThe starter catalog uses @app/ for example destinations relative to the application folder. The editor shows their actual locations. Keep the supplied Examples folder with a portable copy. Your own destinations use their full paths. Task documents and Checklists have separate locations in Settings > Tasks."),
        new Topic("Search and pinned links","Use the Search box to find a saved project, document or website across categories. Search still covers all links when the All links sidebar button is hidden. Clear the search to show every entry or select a category to browse it.\r\n\r\nSelect the star to add a link to your favorites. Favorites appear first in sections that use the default order. A custom order takes precedence. Click the star again to remove a favorite. Use View > Refresh directory to reload saved changes to your dashboard links."),
        new Topic("Tasks and done items","Each task list displays its own selected text document and lets you edit that file. Each item has one title and a brief description. Details keeps its supplied Status, Next and longer notes collapsed initially. Repeated document headings are kept in Source and full document rather than stacked above the tasks. Deferred work is separate under Deferred work · Do not start. Viewing a task does not authorize or start it.\n\nUse Edit below the lists to add, change or remove checklist items. Check an item to move it to Done, or uncheck it in Done to restore it. Checkoffs save automatically in the selected checklist JSON. Existing entries and custom labels are preserved."),
        new Topic("Editing task lists","Choose Edit below the lists in the Tasks sidebar to organize task lists and Checklists in one window. Drag a list by its handle to change the sidebar order. Select a list to rename it, choose a source, or remove it from the Tasks sidebar. Remove from Tasks keeps the source file. Choose Show in Tasks to bring the tab back. Add, edit or remove items in the right pane. Done stages the item, Save applies the pending changes, and Cancel discards changes you have not saved. If a source file changes while you edit, Dashboard shows the conflict.\n\nSelect a task in the editor and use Edit item to change its title, brief description and longer notes. Supplied Status/Next fields and other tasks are kept. An unusual task opens as complete task text so unfamiliar information remains editable.\n\nAdd item puts a new numbered task after the last task in the file, keeping existing numbers. Use Edit document to put it under a different heading. Edit document opens the full selected file, including plain text with no task fields. It can also be used to rearrange text. Drag an item by its handle to reorder it. Use Edit document to move a task across headings. Select an item and confirm Remove item to stage its removal.\n\nSave writes to the same file shown in Source and full document. Cancel leaves it unchanged. A single Updated line before the first task is refreshed when content changes. Existing encoding and line endings are kept by task editing. Whole-document editing saves the text you enter.\n\nIf the file or its selected location changes while you edit, Save refuses to overwrite it and keeps your draft open. Copy anything you need, cancel, Refresh and reopen the latest document. A locked or read-only file reports an error without replacing it.\n\nCheckoffs in the main Checklists view save immediately."),
        new Topic("Get help from an agent","In setup, choose Set up with an AI assistant, then Copy instructions for AI chat. Open your AI chat, paste the instructions and send them. The assistant will ask what you want and show you a plan. With desktop access, it can apply the plan after you approve it. Otherwise, it can give you the exact steps and task-file text. Open Help > Run setup again to get the instructions later. Start Here.txt beside LocalDashboard.exe contains the same instructions and can be attached to an AI chat before the app opens.\n\nTo get help editing a selected task file, turn on Show agent edit prompts in Settings > Tasks. In a task list or Checklists, choose Agent prompt, review it, and copy it into your AI chat. A task-list prompt includes the selected file path. Share it only if you want the agent to see that path. After the file is edited, choose Refresh to read the latest copy."),
        new Topic("Window and startup","Close to the system tray keeps Dashboard running when you click X. With that option off, X quits. Minimize to the system tray hides Dashboard near the Windows clock. With that option off, Minimize keeps it on the taskbar. Double-click the tray icon to return to your current view. Right-click it and choose Open Dashboard, Open Tasks, or Exit. You can also quit through File > Exit.\n\nStart minimized applies when you open Dashboard and when Windows starts it. Dashboard and Compact view remember separate sizes and positions. To restore both defaults, choose Reset window sizes and then Save."),
        new Topic("Formatting task documents","Recommended format, not a requirement\n\n1. Short task title\n   A brief description in ordinary language.\n   Status: Optional supplied status.\n   Next: Optional supplied next step.\n\n   Notes:\n   Longer explanations, references and background go here.\n\nThe task title and brief description stay visible. Dashboard displays consecutive numbers in the task view and keeps the original identifier in Details and Source and full document. Details contains longer notes and supplied Status/Next fields and starts collapsed. A repeated single-project heading can supply the displayed title; Details retains the original task title. Several jobs keep distinct titles and project context. Do not add Status or Next merely to satisfy the app. Task: and Description: are also recognized when supplied.\n\nGroup projects with ### Project name. Put deferred work under ## Later / on hold: do not start now. A project may have several jobs numbered 1.1, 1.2 and so on, each with its own supplied status and next step. Preserve useful source numbers and references.\n\nPlain text with no recognized task headings is shown as written. Mixed documents preserve unrecognized paragraphs and labels too. Multiple Status/Next fields in one older item stay together in Details rather than assigning the last status to the whole project. Source and full document keeps every original heading, instruction and paragraph available.\n\nYou can give this format guide to anyone who edits the same file outside Dashboard. Keep task identifiers and any useful references when editing the source. Use Updated at the top of the document if you want to record when the list last changed.\n\nReading and Refresh do not rewrite formatting. An explicit Save in the task editor changes the selected file. HTML rendering and automatic task execution are not supported."),
        new Topic("Task files and refresh","In Settings > Tasks, choose Choose source… to create a task file or select an existing TXT or Markdown file. You can also open Tasks settings from Set up this list, including in Compact view. Save connects the file and adds its tab if it is Task list 2 or Task list 3. Rename changes the tab label. Disconnect and Save clear the selection and hide an extra tab. Dashboard keeps the file.\n\nChecklists autosaves to its default file. To use an existing Dashboard checklist JSON, choose Choose checklist file and Save. Settings shows the active path. Use default checklist and Save switches back to the default file and preserves both checklists.\n\nOpening a task tab rereads its selected file. Refresh beside Search rereads the current tab. A failed read retains the last good snapshot and reports that it may be out of date.\n\nLocal TXT and Markdown files can be up to 1 MiB. Use readable UTF-8, or a text file with a supported encoding marker. A file in a sync folder must be available locally; its sync application handles sign-in and synchronization. Network shares use existing Windows permissions."),
        new Topic("Always on top, Hide and Close","Choose the pin at the top of Dashboard or View > Always on top to keep the window above other windows. A filled pin shows when the option is on. Choose it again to turn it off.\r\n\r\nWhen Dashboard is in the system tray near the Windows clock, double-click its icon or right-click it and choose Show to return. Opening the same launcher again also brings its window back.\r\n\r\nIn Settings > Window, Close to the system tray and Minimize to the system tray are both on by default. Turning off Close to the system tray makes X quit. Turning off Minimize to the system tray keeps Dashboard on the taskbar when minimized. Start when I sign in to Windows and Start minimized are both off on a fresh profile. Start minimized applies to manual launches and Windows sign-in. File > Exit and the tray menu Exit quit Dashboard."),
        new Topic("Accent color","Settings opens on Appearance. It offers System, Light and Dark with immediate preview. Named swatches are coordinated with the chosen theme. Custom color offers Hue, Saturation and Brightness sliders, and the hex field accepts an exact six-digit color. Reset restores the default for the displayed theme. Each theme remembers its selected accent when saved.\r\n\r\nThe sample card, main window, command icons, window icon, system tray and taskbar icon preview the selected color while Settings is open. Icon color uses your exact selection; text and focus use a readable shade. Save keeps your changes. Cancel or closing Settings restores the last saved appearance."),
        new Topic("Saved data and update conflicts","Each installed or portable copy has a data folder beside its executable. It holds catalog.json and the .local settings folder. Upgrades preserve your catalog, settings and checklist. When uninstalling, choose Keep settings to reuse your setup later or Remove settings to clear settings, links and favorites. Task files and checklist data stay in place. Each copy uses its own data folder.\n\nTask lists read the files you selected. Cached snapshots are separate from their originals. A task list saves only when you explicitly choose Save. Dashboard saves Checklists automatically. Current and Done are views of the same checklist. Edit an item and choose Delete item to remove it from the checklist.\n\nIf another update saved first, an outdated edit is rejected. Refresh and review the latest version before trying again. A damaged or unsupported checklist is not replaced with an empty one. Use Back up configuration before moving or manually editing data."),
        new Topic("Synced task files","To use a file already synced to this PC, choose Choose existing file for its local TXT or Markdown copy in Settings > Tasks and make it available offline. Your sync application handles sign-in and synchronization. Refresh reads the local copy. Saving a task list edits that copy, and your sync application handles uploading it. Dashboard cannot confirm that it matches the online version. Checklists uses Dashboard's checklist format. HTML documents are not supported as task-list sources."),
        new Topic("Configuration backups","File > Back up configuration saves dashboard links, settings, favorites, layout and custom icons, plus available copies of your task lists and Checklists. The result reports unavailable copies. Linked files and folders need their own backups.\n\nChoose Restore from a backup on the first setup screen, or File > Restore configuration from the Dashboard. Before restoring, Dashboard saves a backup of your current configuration. It reconnects included custom icons automatically. It saves restored task lists as new files. Review the choice for each list. Dashboard defaults to keeping a working list or using the restored copy if no current file is set up or Dashboard can't open it. A missing backup copy leaves the current selection intact. Windows sign-in startup keeps its setting on this PC.\n\nSelecting a standalone catalog.json in Restore configuration offers a separate Import links confirmation. It shows the link count and replaces only dashboard links, preserving settings and task-list selections. A copy of the previous catalog is retained in the data folder. Relative example paths keep their source location; linked files are not copied. All links shows every imported entry.\n\nDashboard reads older backups. When included, the first two text-list copies restore to Task list 1 and Task list 2. A backup without a third list keeps the current Task list 3 selection. If a backup contains only the path to an icon, Dashboard uses the original image when it is available. You can choose a replacement in Edit Dashboard if the file is missing."),
        new Topic("Optional setup","On the welcome screen, choose Restore from a backup if you have a saved configuration. A successful restore finishes setup. Choose Next to add a link of your own or select task files. Both steps are optional. Finish saves the link and files you chose. Use Edit below the sidebar to add more links. Help > Run setup again reopens the walkthrough.\n\nIn Settings > Tasks, use Rename beside a task section to change its button label. Dashboard saves your checklist automatically."),
        new Topic("Check for updates","Choose Help > Check for updates to compare your version with the latest stable GitHub release. If a newer release is available, choose View release to open its page in your browser. If the check fails, try again when GitHub is reachable. Exit Dashboard before running a new installer or replacing your portable executable."),
        new Topic("Report an issue","Help > Report an issue asks what you were doing, what you expected, and what happened instead. The labels stay fixed, and Local Dashboard includes its version automatically. Copy report includes the version, prompts and your answers. Paste it into your message on the DGX Development contact page. Nothing is sent automatically."),
        new Topic("One running Dashboard","Local Dashboard 2.2.0 and newer share one running instance per Windows user, across builds and profiles. Opening it again brings the existing window forward. Exit the running version before opening a different build. This version also refuses to start while it detects an older Dashboard in your Windows session. Older builds cannot honor the new guard if launched afterward; use the current shortcut and retire obsolete launchers. Your lists and profile are never switched or forcibly closed."),
        new Topic("Troubleshooting","If a folder or document does not open, check that it still exists. Correct a moved destination in Edit Dashboard, then choose Save.\r\n\r\nIf Checklist unavailable appears, checkoffs are disabled until the saved file can be read safely. Existing data is left unchanged. Ask for help repairing the file rather than deleting or overwriting it.\r\n\r\nIf Dashboard opens behind another window, choose its taskbar button. If it is hidden in the tray, double-click its notification-area icon or reopen its launcher.\r\n\r\nF1 opens this guide. Ctrl+R refreshes the directory, Ctrl+Shift+C opens Tasks, and Ctrl+Q exits.")
    };
    readonly TextBox search=new TextBox();readonly ListBox topics=new ListBox();readonly Label title=new Label();readonly Label article=new Label();readonly Panel articleHost=new Panel();bool fittingArticle;
    internal DashboardHelp():base("Help & user guide",new Size(1020,760)){
        MinimumSize=new Size(780,500);
        var heading=Label("Help & user guide",new Font("Segoe UI Variable Display",21,FontStyle.Bold),DashboardForm.Ink);Controls.Add(heading);
        var subtitle=Label("Find a topic or search for a word.",Font,DashboardForm.Muted);Controls.Add(subtitle);
        var searchLabel=Label("Search help",Font,DashboardForm.Ink);Controls.Add(searchLabel);
        search.BackColor=DashboardForm.Surface;search.ForeColor=DashboardForm.Ink;search.BorderStyle=BorderStyle.FixedSingle;search.AccessibleName="Search help";Controls.Add(search);
        topics.BackColor=DashboardForm.Surface;topics.ForeColor=DashboardForm.Ink;topics.BorderStyle=BorderStyle.None;topics.IntegralHeight=false;topics.ItemHeight=42;topics.DrawMode=DrawMode.OwnerDrawFixed;topics.AccessibleName="Help topics";Controls.Add(topics);
        title.Font=new Font("Segoe UI Variable Display",15,FontStyle.Bold);title.ForeColor=DashboardForm.Ink;title.UseMnemonic=false;Controls.Add(title);
        article.UseMnemonic=false;article.BackColor=DashboardForm.Background;article.ForeColor=DashboardForm.Ink;article.Font=Font;article.AccessibleName="Help topic text";articleHost.AutoScroll=true;articleHost.BackColor=DashboardForm.Background;articleHost.Controls.Add(article);Controls.Add(articleHost);articleHost.Resize+=(s,e)=>FitArticle();
        var close=DashboardForm.LinkButton("Close");close.DialogResult=DialogResult.Cancel;Controls.Add(close);CancelButton=close;
        var maintenance=new LinkLabel{Text="Open maintenance guide",LinkColor=DashboardForm.Accent,ActiveLinkColor=DashboardForm.Ink,VisitedLinkColor=DashboardForm.Accent,AccessibleName="Open human maintenance source guide"};maintenance.LinkClicked+=(s,e)=>{try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(AppData.Root,".dev","Human Maintenance.md")){UseShellExecute=true});}catch(Exception error){MessageBox.Show(this,error.Message,Text,MessageBoxButtons.OK,MessageBoxIcon.Warning);}};Controls.Add(maintenance);
        topics.DrawItem+=(s,e)=>{if(e.Index<0)return;using(var fill=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(56,56,56):DashboardForm.Surface))e.Graphics.FillRectangle(fill,e.Bounds);TextRenderer.DrawText(e.Graphics,topics.Items[e.Index].ToString(),Font,Rectangle.Inflate(e.Bounds,-10,0),DashboardForm.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);e.DrawFocusRectangle();};
        topics.SelectedIndexChanged+=(s,e)=>{var topic=topics.SelectedItem as Topic;if(topic!=null){title.Text=topic.Title;article.Text=topic.Body;articleHost.AutoScrollPosition=Point.Empty;FitArticle();}};
        search.TextChanged+=(s,e)=>Filter();Action layout=()=>{int nav=240,left=28;heading.SetBounds(left,20,ClientSize.Width-56,40);subtitle.SetBounds(left+2,65,ClientSize.Width-60,28);searchLabel.SetBounds(left,112,nav,22);search.SetBounds(left,140,nav,26);topics.SetBounds(left,182,nav,Math.Max(40,ClientSize.Height-270));maintenance.SetBounds(left,ClientSize.Height-58,nav,38);title.SetBounds(left+nav+28,112,Math.Max(80,ClientSize.Width-nav-84),38);articleHost.SetBounds(left+nav+28,162,Math.Max(80,ClientSize.Width-nav-84),Math.Max(40,ClientSize.Height-240));FitArticle();close.SetBounds(ClientSize.Width-138,ClientSize.Height-58,110,38);};Resize+=(s,e)=>layout();layout();Filter();
    }
    void FitArticle(){if(fittingArticle)return;fittingArticle=true;try{int width=Math.Max(80,articleHost.ClientSize.Width-16);article.Width=width;article.Height=TextRenderer.MeasureText(article.Text,article.Font,new Size(width,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl).Height+8;articleHost.AutoScrollMinSize=new Size(0,article.Height);}finally{fittingArticle=false;}}
    void Filter(){topics.BeginUpdate();topics.Items.Clear();string query=search.Text.Trim();foreach(var topic in Topics.Where(t=>(t.Title+" "+t.Body).IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0))topics.Items.Add(topic);topics.EndUpdate();if(topics.Items.Count>0)topics.SelectedIndex=0;else{title.Text="No matching topics";article.Text="Try a word such as folder, Done, Hide or saved data.";FitArticle();}}
    internal void Verify(){search.Text="checkoffs";if(topics.Items.Count==0)throw new Exception("Guide search found no expected topic.");search.Text="no-such-help-topic-914827";if(topics.Items.Count!=0||title.Text!="No matching topics")throw new Exception("Guide empty search failed.");search.Text="";if(topics.Items.Count!=Topics.Length)throw new Exception("Guide reset failed.");}
    protected override bool ProcessCmdKey(ref Message message,Keys keyData){if(keyData==(Keys.Control|Keys.F)){search.Focus();return true;}return base.ProcessCmdKey(ref message,keyData);}
}







